// Smart case conversion function for entire document
function analyzeDocumentCase() {
    let totalUppercaseCount = 0;
    let totalLowercaseCount = 0;

    // Analyze all text inputs and textareas together
    document.querySelectorAll('input[type="text"], textarea').forEach(function(element) {
        if (element.value) {
            for (let char of element.value) {
                if (char >= 'A' && char <= 'Z') {
                    totalUppercaseCount++;
                } else if (char >= 'a' && char <= 'z') {
                    totalLowercaseCount++;
                }
            }
        }
    });

    // Return the majority case for the entire document
    if (totalUppercaseCount > totalLowercaseCount) {
        return 'upper';
    } else if (totalLowercaseCount > totalUppercaseCount) {
        return 'lower';
    }
    return 'none'; // Equal or no letters
}

// Apply document-wide case conversion
function applyDocumentCaseConversion() {
    const documentCase = analyzeDocumentCase();

    if (documentCase !== 'none') {
        document.querySelectorAll('input[type="text"], textarea').forEach(function(element) {
            if (element.value) {
                if (documentCase === 'upper') {
                    element.value = element.value.toUpperCase();
                } else if (documentCase === 'lower') {
                    element.value = element.value.toLowerCase();
                }
            }
        });
    }
}

